def _decode_data(b64_str: str, is_json: bool = True) -> Any:
    """Decode base64 encoded data with error handling for corrupted/placeholder values."""
    try:
        # Check for placeholder strings (not yet substituted)
        if b64_str.startswith('$') or not b64_str:
            return None
        raw = base64.b64decode(b64_str)
        if _DATA_COMPRESSED:
            import zlib
            raw = zlib.decompress(raw)
        if is_json:
            return json.loads(raw.decode('utf-8'))
        return raw
    except Exception as e:
        # Return None for any decode failure - callers should provide fallback defaults
        print(f"[WARN] Failed to decode embedded data: {e}")
        return None


def _safe_print(text: str):
    """Print text safely on Windows (handle emoji/unicode errors)."""
    try:
        print(text)
    except UnicodeEncodeError:
        # Fallback: strip non-ASCII characters
        print(text.encode('ascii', 'replace').decode('ascii'))


def _safe_input(prompt: str) -> str:
    """Input with safe prompt on Windows (handle emoji/unicode errors)."""
    try:
        return input(prompt)
    except UnicodeEncodeError:
        # Fallback: strip non-ASCII characters from prompt
        safe_prompt = prompt.encode('ascii', 'replace').decode('ascii')
        return input(safe_prompt)


def _decode_brain(b64_str: str) -> bytes:
    raw = base64.b64decode(b64_str)
    if _DATA_COMPRESSED:
        import zlib
        raw = zlib.decompress(raw)
    return raw


